  "description": "Barthel Index（BI）の10項目や採点基準、FIMとの違い（できるADLとしているADL等）を解説。理学療法士や学生向けに、評価項目、採点段階、臨床での使い分けや注意点を分かりやすくまとめています。",
  "category": "評価・検査",
