   {
    "t": "note",
    "x": "各課題の詳しい採点基準は、公式の検査用紙や、使っている教科書で確認してください。ここでは、基準の全文は載せていません。"
   },
   {
    "t": "h2",
    "x": "報告されているカットオフ値・目安"
   },
   {
    "t": "table",
    "head": [
     "値・区分",
     "意味（資料での説明）",
     "対象・根拠（資料の記載）"
    ],
    "rows": [
     [
      "45点未満（45点以下とする資料もある）",
      "転倒リスクありの目安",
      "原著のBerg（1989・1992）とされることが多い。国家試験でも問われる"
     ],
     [
      "49点未満",
      "脳卒中患者の転倒リスク",
      "Beninato ら（2009）と紹介されている"
     ],
     [
      "0〜20点",
      "車椅子レベル",
      "Shumway-Cook ら（1997）、Blum ら（2008）と紹介されている"
     ],
     [
      "21〜40点",
      "介助での歩行レベル（転倒リスクが高い）",
      "同上"
     ],
     [
      "41〜56点",
      "自立歩行レベル",
      "同上（45〜56点では、1点下がるごとに、転倒リスクが約6〜8%上がるとする資料もある）"
     ]
    ]
   },
   {
    "t": "h2",
    "x": "資料によって値が違う点"
   },
   {
    "t": "ul",
    "items": [
     "転倒リスクの目安は、多くの資料で「45点未満（以下）」ですが、ある介護施設の資料では「37点未満」など、別の区分も使われています。",
     "脳卒中では、研究の対象や時期（急性期・慢性期）によって、29〜52点と、幅のある値が報告されています。1つの値だけを、すべての人に当てはめないようにしましょう。",
     "測定にかかる時間も、資料によって、10〜30分と幅があります。"
    ]
   },
   {
    "t": "h2",
    "x": "測定するときの注意"
   },
   {
    "t": "ul",
    "items": [
     "片脚立位・タンデム立位・踏み台のステップなど、転倒しやすい課題では、すぐ支えられる位置で見守ります。",
     "保持する課題（2分・1分・30秒・10秒）は、目測ではなく、ストップウォッチで測ります。",
     "原則は、杖や歩行器を使わずに行います。使った場合は、その条件を記録し、次回以降も同じ条件にそろえます（補助具を使うと0点とする基準もあります）。",
     "椅子の高さや踏み台の高さなど、道具の条件をそろえます。",
     "歩ける人では満点に近く差が出にくく（天井効果）、座位も難しい人では、最初の課題で止まる（床効果）ため、必要に応じて、他の検査と組み合わせます。"
    ]
   },
   {
    "t": "note",
    "x": "カットオフ値は、診断のための絶対的な基準ではなく、目安です。対象者の状態や、他の評価とあわせて判断してください。"
   }
