    "t": "p",
    "x": "ボルグ指数（Borg scale）は、運動中のきつさを、本人の感覚で数字にする指標で、自覚的運動強度（RPE：Rating of Perceived Exertion）として使われます。日本循環器学会のガイドラインでは、運動負荷試験を行えない場合などに、トレーニング強度を決める方法の1つとして、ボルグ指数が紹介されています。"
