    "x": "MDS-UPDRSはH&Y分類をサブコンポーネントとして含んでおり、H&Yステージが進むにつれてMDS-UPDRSの各パートスコアも有意に増加する強い相関関係が確認されています。ただし、H&Y分類は変化に対する感度が低いため、理学療法効果の判定にはMDS-UPDRS（Part II・III）や各種歩行・バランス評価指標（TUG、10m歩行テスト等）を併用することが推奨されます。"
