    "x": "地域包括ケアシステムは、高齢者が、可能な限り住み慣れた地域で、自分らしい暮らしを人生の最期まで続けられるようにするための、地域の包括的な支援・サービス提供体制です。厚生労働省は、高齢者の尊厳の保持と自立生活の支援を目的として、その構築を推進しています。"
