     "HDS-Rのカットオフ値：一般的に20点以下（20/21点）で認知症が疑われるとされる。",
     "HDS-Rの開発時の文献では、得点による機械的な重症度分類を行わず、どの項目を誤答したかの分析を重視するとされている。"
