    "t": "p",
    "x": "パーキンソン病は中脳黒質緻密部のドーパミン神経細胞変性を主徴とする緩徐進行性の神経変性疾患です。安静時振戦、筋固縮、無動・動作緩慢、姿勢反射障害の四大運動症状に加え、自律神経障害や認知・精神症状などの非運動症状を呈します。薬物療法と並び、早期からの計画的な理学療法介入が運動機能やQOLの維持・向上に不可欠とされています。"
